class Qwen3VLVisionModel(Qwen3VLPreTrainedModel):
    config: Qwen3VLVisionConfig
    input_modalities = ("image", "video")
    _can_record_outputs = {
        "hidden_states": Qwen3VLVisionBlock,
        "attentions": Qwen3VLVisionAttention,
    }

    def __init__(self, config, *inputs, **kwargs) -> None:
        super().__init__(config, *inputs, **kwargs)
        self.spatial_merge_size = config.spatial_merge_size
        self.patch_size = config.patch_size
        self.spatial_merge_unit = self.spatial_merge_size * self.spatial_merge_size

        self.patch_embed = Qwen3VLVisionPatchEmbed(
            config=config,
        )

        self.pos_embed = nn.Embedding(config.num_position_embeddings, config.hidden_size)
        self.num_grid_per_side = int(config.num_position_embeddings**0.5)

        head_dim = config.hidden_size // config.num_heads
        self.rotary_pos_emb = Qwen3VLVisionRotaryEmbedding(head_dim // 2)

        self.blocks = nn.ModuleList([Qwen3VLVisionBlock(config) for _ in range(config.depth)])
        self.merger = Qwen3VLVisionPatchMerger(
            config=config,
            use_postshuffle_norm=False,
        )

        self.deepstack_visual_indexes = config.deepstack_visual_indexes
        self.deepstack_merger_list = nn.ModuleList(
            [
                Qwen3VLVisionPatchMerger(
                    config=config,
                    use_postshuffle_norm=True,
                )
                for _ in range(len(config.deepstack_visual_indexes))
            ]
        )

        self.gradient_checkpointing = False

        self.post_init()

    def rot_pos_emb(self, grid_thw: torch.Tensor) -> torch.Tensor:
        warnings.warn(
            f"`{self.__class__.__name__}.rot_pos_emb` is deprecated and will be removed in v5.11. Use `get_vision_position_ids` from `transformers.vision_utils` and apply the rotary embedding module.",
            FutureWarning,
            stacklevel=2,
        )
        position_ids = get_vision_position_ids(grid_thw, self.spatial_merge_size)
        rotary_pos_emb = self.rotary_pos_emb(position_ids)
        return rotary_pos_emb

    def fast_pos_embed_interpolate(self, grid_thw):
        warnings.warn(
            f"`{self.__class__.__name__}.fast_pos_embed_interpolate` is deprecated and will be removed in v5.11. Use `get_vision_bilinear_indices_and_weights` from `transformers.vision_utils` and apply `self.pos_embed`.",
            FutureWarning,
            stacklevel=2,
        )
        bilinear_indices, bilinear_weights = get_vision_bilinear_indices_and_weights(
            grid_thw,
            num_grid_per_side=self.num_grid_per_side,
            spatial_merge_size=self.config.spatial_merge_size,
        )
        return (self.pos_embed(bilinear_indices) * bilinear_weights[:, :, None]).sum(0)

    @merge_with_config_defaults
    @capture_outputs
    def forward(
            self, hidden_states: torch.Tensor, grid_thw: torch.Tensor, **kwargs: Unpack[TransformersKwargs]
    ) -> tuple | BaseModelOutputWithDeepstackFeatures:
        """
        Args:
            hidden_states (`torch.Tensor` of shape `(seq_len, hidden_size)`):
                The final hidden states of the model.
            grid_thw (`torch.Tensor` of shape `(num_images_or_videos, 3)`):
                The temporal, height and width of feature shape of each image in LLM.

        Returns:
            `torch.Tensor`: hidden_states.
        """
        bilinear_indices, bilinear_weights = get_vision_bilinear_indices_and_weights(
            grid_thw,
            num_grid_per_side=self.num_grid_per_side,
            spatial_merge_size=self.config.spatial_merge_size,
            kwargs=kwargs,
        )
        position_ids = get_vision_position_ids(grid_thw, self.spatial_merge_size, kwargs=kwargs)
        cu_seqlens = get_vision_cu_seqlens(grid_thw, kwargs=kwargs)

        hidden_states = self.patch_embed(hidden_states)
        pos_embeds = (self.pos_embed(bilinear_indices) * bilinear_weights[:, :, None]).sum(0)
        hidden_states = hidden_states + pos_embeds.to(hidden_states.dtype)
        rotary_pos_emb = self.rotary_pos_emb(position_ids)

        seq_len, _ = hidden_states.size()
        hidden_states = hidden_states.reshape(seq_len, -1)
        rotary_pos_emb = rotary_pos_emb.reshape(seq_len, -1)
        emb = torch.cat((rotary_pos_emb, rotary_pos_emb), dim=-1)
        position_embeddings = (emb.cos(), emb.sin())

        deepstack_feature_lists = []
        for layer_num, blk in enumerate(self.blocks):
            hidden_states = blk(
                hidden_states,
                cu_seqlens=cu_seqlens,
                position_embeddings=position_embeddings,
                **kwargs,
            )
            if layer_num in self.deepstack_visual_indexes:
                deepstack_feature = self.deepstack_merger_list[self.deepstack_visual_indexes.index(layer_num)](
                    hidden_states
                )
                deepstack_feature_lists.append(deepstack_feature)

        merged_hidden_states = self.merger(hidden_states)

        return BaseModelOutputWithDeepstackFeatures(
            last_hidden_state=hidden_states,
            pooler_output=merged_hidden_states,
            deepstack_features=deepstack_feature_lists,
        )


@auto_docstring(
    custom_intro=(
            "Text part of Qwen3VL, "
            "not a pure text-only model, as DeepStack integrates visual features into the early hidden states."
    )
)
class Qwen3VLTextModel(Qwen3VLPreTrainedModel):
    config: Qwen3VLTextConfig
    input_modalities = ("text",)

    def __init__(self, config: Qwen3VLTextConfig):
        super().__init__(config)
        self.padding_idx = config.pad_token_id
        self.vocab_size = config.vocab_size

        self.embed_tokens = nn.Embedding(config.vocab_size, config.hidden_size, self.padding_idx)
        self.layers = nn.ModuleList(
            [Qwen3VLTextDecoderLayer(config, layer_idx) for layer_idx in range(config.num_hidden_layers)]
        )
        self.norm = Qwen3VLTextRMSNorm(config.hidden_size, eps=config.rms_norm_eps)
        self.rotary_emb = Qwen3VLTextRotaryEmbedding(config=config)
        self.gradient_checkpointing = False

        # Initialize weights and apply final processing
        self.post_init()

    @merge_with_config_defaults
    @capture_outputs
    @auto_docstring
    def forward(
            self,
            input_ids: torch.LongTensor | None = None,
            attention_mask: torch.Tensor | None = None,
            position_ids: torch.LongTensor | None = None,
            past_key_values: Cache | None = None,
            inputs_embeds: torch.FloatTensor | None = None,
            use_cache: bool | None = None,
            # args for deepstack
            visual_pos_masks: torch.Tensor | None = None,
            deepstack_visual_embeds: list[torch.Tensor] | None = None,
            **kwargs: Unpack[FlashAttentionKwargs],
    ) -> tuple | BaseModelOutputWithPast:
        r"""
        visual_pos_masks (`torch.Tensor` of shape `(batch_size, seqlen)`, *optional*):
            The mask of the visual positions.
        deepstack_visual_embeds (`list[torch.Tensor]`, *optional*):
            The deepstack visual embeddings. The shape is (num_layers, visual_seqlen, embed_dim).
            The feature is extracted from the different visual encoder layers, and fed to the decoder
            hidden states. It's from the paper DeepStack(https://arxiv.org/abs/2406.04334).
        """
        if (input_ids is None) ^ (inputs_embeds is not None):
            raise ValueError("You must specify exactly one of input_ids or inputs_embeds")

        # torch.jit.trace() doesn't support cache objects in the output
        if use_cache and past_key_values is None and not torch.jit.is_tracing():
            past_key_values = DynamicCache(config=self.config)

        if inputs_embeds is None:
            inputs_embeds = self.embed_tokens(input_ids)

        # the hard coded `4` is for text, temporal, height and width.
        if position_ids is None:
            past_seen_tokens = past_key_values.get_seq_length() if past_key_values is not None else 0
            position_ids = torch.arange(inputs_embeds.shape[1], device=inputs_embeds.device) + past_seen_tokens
            position_ids = position_ids.view(1, 1, -1).expand(4, inputs_embeds.shape[0], -1)
        elif position_ids.ndim == 2:
            position_ids = position_ids[None, ...].expand(4, position_ids.shape[0], -1)

        if position_ids.ndim == 3 and position_ids.shape[0] == 4:
            text_position_ids = position_ids[0]
            position_ids = position_ids[1:]
        else:
            text_position_ids = None

        attention_mask = create_causal_mask(
            config=self.config,
            inputs_embeds=inputs_embeds,
            attention_mask=attention_mask,
            past_key_values=past_key_values,
            position_ids=text_position_ids,
        )

        hidden_states = inputs_embeds

        # create position embeddings to be shared across the decoder layers
        position_embeddings = self.rotary_emb(hidden_states, position_ids)

        # decoder layers
        for layer_idx, decoder_layer in enumerate(self.layers):
            layer_outputs = decoder_layer(
                hidden_states,
                attention_mask=attention_mask,
                position_ids=text_position_ids,
                past_key_values=past_key_values,
                position_embeddings=position_embeddings,
                **kwargs,
            )
            hidden_states = layer_outputs

            # add visual features to the hidden states of first several layers
            if deepstack_visual_embeds is not None and layer_idx in range(len(deepstack_visual_embeds)):
                hidden_states = self._deepstack_process(
                    hidden_states,
                    visual_pos_masks,
                    deepstack_visual_embeds[layer_idx],
                )

        hidden_states = self.norm(hidden_states)

        return BaseModelOutputWithPast(
            last_hidden_state=hidden_states,
            past_key_values=past_key_values,
        )

    def _deepstack_process(
            self, hidden_states: torch.Tensor, visual_pos_masks: torch.Tensor, visual_embeds: torch.Tensor
    ):
        visual_pos_masks = visual_pos_masks.to(hidden_states.device)
        visual_embeds = visual_embeds.to(hidden_states.device, hidden_states.dtype)
        hidden_states = hidden_states.clone()
        local_this = hidden_states[visual_pos_masks, :] + visual_embeds
        hidden_states[visual_pos_masks, :] = local_this
        return hidden_states


@auto_docstring
class Qwen3VLModel(Qwen3VLPreTrainedModel):
    """
    Args:
        save_redundancy (`bool`, *optional*, defaults to `False`):
            Whether to retain singleton unselected visual tokens.
        keep_ratio (`float`, *optional*, defaults to 0.8):
            Target fraction of visual tokens to retain (AQTC four-quadrant).
        memory_capacity (`int`, *optional*, defaults to 256):
            Maximum number of compressed visual tokens stored as novelty history.
        query_weight (`float`, *optional*, defaults to 0.4):
            Weight of query relevance in the AQTC importance fusion.
        saliency_weight (`float`, *optional*, defaults to 0.3):
            Weight of visual saliency in the AQTC importance fusion.
        novelty_frames_per_segment (`int`, *optional*, defaults to 4):
            Frames per novelty/compression segment.
        dynamic_segment_budget (`bool`, *optional*, defaults to `False`):
            Enable per-segment variable keep_ratio allocation.
        dynamic_budget_strength (`float`, *optional*, defaults to 0.5):
            Strength of dynamic budget deviation from base keep_ratio.
        budget_ceiling (`float`, *optional*, defaults to 0.45):
            Maximum keep_ratio any segment can receive.
        temporal_aware (`bool`, *optional*, defaults to `False`):
            Enable temporal-aware novelty precomputation with causal memory.
        temporal_weight (`float`, *optional*, defaults to 0.2):
            Weight of temporal novelty in dynamic segment budget allocation.
        temporal_protect_ratio (`float`, *optional*, defaults to 0.15):
            Fraction of high-novelty tokens protected via argmax override.
    """
    base_model_prefix = "model"
    # Reference: fix gemma3 grad acc #37208
    accepts_loss_kwargs = False

    def __init__(
            self,
            config,
            save_redundancy: bool = False,
            keep_ratio: float = 0.8,
            memory_capacity: int = 256,
            query_weight: float = 0.4,
            saliency_weight: float = 0.3,
            novelty_frames_per_segment: int = 4,
            dynamic_segment_budget: bool = False,
            dynamic_budget_strength: float = 0.5,
            budget_ceiling: float = 0.45,
            temporal_aware: bool = False,
            temporal_weight: float = 0.2,
            temporal_protect_ratio: float = 0.15,
    ):
        """Build the multimodal model with AQTC visual-token compression.

        Args:
            save_redundancy (`bool`, *optional*, defaults to `False`):
                Whether to retain singleton unselected visual
                tokens. Contiguous unselected visual tokens are still pooled
                into one token.
            keep_ratio (`float`, *optional*, defaults to 0.8):
                Target fraction of visual tokens to retain.
            memory_capacity (`int`, *optional*, defaults to 256):
                Maximum number of compressed visual tokens stored as novelty history.
            query_weight (`float`, *optional*, defaults to 0.4):
                Weight of query relevance in importance fusion.
            saliency_weight (`float`, *optional*, defaults to 0.3):
                Weight of visual saliency in importance fusion.
            novelty_frames_per_segment (`int`, *optional*, defaults to 4):
                Frames per novelty/compression segment.
            dynamic_segment_budget (`bool`, *optional*, defaults to `False`):
                Enable per-segment variable budget.
            dynamic_budget_strength (`float`, *optional*, defaults to 0.5):
                Strength of dynamic budget deviation.
            budget_ceiling (`float`, *optional*, defaults to 0.45):
                Maximum keep_ratio per segment.
            temporal_aware (`bool`, *optional*, defaults to `False`):
                Enable temporal-aware novelty with causal memory.
            temporal_weight (`float`, *optional*, defaults to 0.2):
                Weight of temporal novelty in budget allocation.
            temporal_protect_ratio (`float`, *optional*, defaults to 0.15):
                Fraction of high-novelty tokens to protect.
        """
        super().__init__(config)
        self.save_redundancy = save_redundancy
        self.visual = AutoModel.from_config(config.vision_config)
        self.language_model = AutoModel.from_config(config.text_config)
        self.rope_deltas = None  # cache rope_deltas here
        self.keep_ratio = keep_ratio
        self.query_weight = query_weight
        self.saliency_weight = saliency_weight
        self.novelty_frames_per_segment = novelty_frames_per_segment
        self.dynamic_segment_budget = dynamic_segment_budget
        self.dynamic_budget_strength = dynamic_budget_strength
        self.budget_ceiling = budget_ceiling
        self.temporal_aware = temporal_aware
        self.temporal_weight = temporal_weight
        self.temporal_protect_ratio = temporal_protect_ratio
        self.novelty_estimator = NoveltyEstimator(config.text_config.hidden_size, memory_capacity)
        self.importance_fusion = ImportanceFusion(query_weight, saliency_weight)
        self.last_importance_scores = None

        # Initialize weights and apply final processing
        self.post_init()
        self.total_original_prefill_tokens = 0
        self.total_compressed_prefill_tokens = 0
        self.total_original_visual_tokens = 0
        self.total_compressed_visual_tokens = 0

    def reset_novelty_memory(self) -> None:
        """Clear visual history before processing an unrelated video."""
        self.novelty_estimator.reset()

    def get_last_importance_scores(self) -> dict[str, torch.Tensor] | None:
        """Return detached score components from the latest visual selection."""
        return self.last_importance_scores

    def get_vision_position_ids(
            self,
            start_position: int,
            grid_thw: list[int, int, int] | torch.Tensor,
            temp_merge_size: int = 1,
            spatial_merge_size: int = 1,
            time_interval: int = 1,
            device: str | torch.device | None = None,
    ):
        """
        Compute 3D positional indices for vision tokens derived from a single image or video input.

        The positions are generated from the input grid defined by temporal (T), height (H), and
        width (W) dimensions. Temporal and spatial dimensions can be downscaled according to the
        merge sizes used in the vision backbone. The resulting positions are offset by `start_position`.

        Args:
            start_position (`int`):
                Offset added to all computed positional indices.
            grid_thw (`Sequence[int]` or `torch.Tensor` of shape `(3,)`):
                The (T, H, W) grid representing the feature layout of the current image or video after patch embedding.
            temp_merge_size (`int`, *optional*):
                Factor by which the temporal dimension is reduced in the backbone. The temporal grid size is divided
                by this value. Defaults to 1.
            spatial_merge_size (`int`, *optional*):
                Factor by which the spatial dimensions (H and W) are reduced in the backbone. Both H and W are divided
                by this value. Defaults to 1.
            time_interval (`int`, *optional*):
                Spacing factor applied between consecutive temporal position indices.Defaults to 1.
            device (`str` or `torch.device`, *optional*):
                Device on which the resulting tensor is allocated. If `None`, uses the current default device.

        Returns:
            torch.LongTensor of shape (3, sequence_length):
                Positional indices for temporal, height, and width dimensions,
                flattened into sequence form and offset by `start_position`.
        """
        llm_grid_t, llm_grid_h, llm_grid_w = (
            grid_thw[0].item() // temp_merge_size,
            grid_thw[1].item() // spatial_merge_size,
            grid_thw[2].item() // spatial_merge_size,
        )

        # Add `start_position` after arange for compile
        position_temporal = torch.arange(llm_grid_t, device=device) * time_interval
        position_width = torch.arange(llm_grid_w, device=device) + start_position
        position_height = torch.arange(llm_grid_h, device=device) + start_position

        # Repeat the positions per each grid and per video frame. Repeat patterns are important
        # do not modify without checking values!
        position_width = position_width.repeat(llm_grid_h * llm_grid_t)
        position_height = position_height.repeat_interleave(llm_grid_w).repeat(llm_grid_t)
        # Important: add `start_positions` after applying `time_interval`, order matters
        position_temporal = position_temporal.repeat_interleave(llm_grid_h * llm_grid_w) + start_position
        vision_position_ids = torch.stack([position_temporal, position_height, position_width], dim=0)

        return vision_position_ids

    def get_rope_index(
            self,
            input_ids: torch.LongTensor,
            mm_token_type_ids: torch.IntTensor,
            image_grid_thw: torch.LongTensor | None = None,
            video_grid_thw: torch.LongTensor | None = None,
            attention_mask: torch.Tensor | None = None,
            **kwargs,
    ) -> tuple[torch.Tensor, torch.Tensor]:
        """
        Difference from Qwen2VL/Qwen2.5VL's get_rope_index:
        - Since Qwen3.5 use timestamps to separate videos, like <t1> <vision_start> <frame1> <vision_end> <t2> <vision_start> <frame2> <vision_end>, the video_grid_thw should also be split too.

        Args:
            input_ids (`torch.LongTensor` of shape `(batch_size, sequence_length)`):
                Indices of input sequence tokens in the vocabulary. Padding will be ignored by default should you provide
                it.
            mm_token_type_ids (`torch.IntTensor` of shape `(batch_size, sequence_length)`):
                Token type ids matching each modality to a different value in the input sequence, i.e. text (0), image (1), video (2).
            image_grid_thw (`torch.LongTensor` of shape `(num_images, 3)`, *optional*):
                The temporal, height and width of feature shape of each image in LLM.
            video_grid_thw (`torch.LongTensor` of shape `(num_videos, 3)`, *optional*):
                The temporal, height and width of feature shape of each video in LLM.
            attention_mask (`torch.Tensor` of shape `(batch_size, sequence_length)`, *optional*):
                Mask to avoid performing attention on padding token indices. Mask values selected in `[0, 1]`:

                - 1 for tokens that are **not masked**,
                - 0 for tokens that are **masked**.

        Returns:
            position_ids (`torch.LongTensor` of shape `(3, batch_size, sequence_length)`)
            mrope_position_deltas (`torch.Tensor` of shape `(batch_size)`)
        """

        # Separate video grid thw into multiple grids because timestamps are used to separate videos.
        if video_grid_thw is not None:
            video_grid_thw = torch.repeat_interleave(video_grid_thw, video_grid_thw[:, 0], dim=0)
            video_grid_thw[:, 0] = 1
        spatial_merge_size = self.config.vision_config.spatial_merge_size

        mrope_position_deltas = []
        position_ids = torch.zeros(
            3,
            input_ids.shape[0],
            input_ids.shape[1],
            dtype=input_ids.dtype,
            device=input_ids.device,
        )
        grid_iters = {
            1: iter(image_grid_thw) if image_grid_thw is not None else None,
            2: iter(video_grid_thw) if video_grid_thw is not None else None,
        }

        for batch_idx, current_input_ids in enumerate(input_ids):
            input_token_type = mm_token_type_ids[batch_idx]
            if attention_mask is not None:
                current_input_ids = current_input_ids[attention_mask[batch_idx].bool()]
                input_token_type = input_token_type[attention_mask[batch_idx].bool()]

            input_type_group = []
            for key, group in itertools.groupby(enumerate(input_token_type.tolist()), lambda x: x[1]):
                group = list(group)
                start_index = group[0][0]
                end_index = group[-1][0] + 1
                input_type_group.append((key, start_index, end_index))

            current_pos = 0
            llm_pos_ids_list = []
            for modality_type, start_idx, end_idx in input_type_group:
                # text == 0
                if modality_type == 0:
                    text_len = end_idx - start_idx
                    llm_pos_ids_list.append(
                        torch.arange(text_len, device=input_ids.device).view(1, -1).expand(3, -1) + current_pos
                    )
                    current_pos += text_len
                # image == 1, video == 2
                else:
                    grid_thw = next(grid_iters[modality_type])
                    vision_position_ids = self.get_vision_position_ids(
                        current_pos, grid_thw, 1, spatial_merge_size, device=input_ids.device
                    )
                    llm_pos_ids_list.append(vision_position_ids)
                    current_pos += max(grid_thw[1], grid_thw[2]) // spatial_merge_size
            llm_positions = torch.cat(llm_pos_ids_list, dim=1).reshape(3, -1)
            if attention_mask is not None:
                position_ids[:, batch_idx, attention_mask[batch_idx].bool()] = llm_positions.to(position_ids.device)
            else:
                position_ids[:, batch_idx] = llm_positions.to(position_ids.device)
            mrope_position_deltas.append(llm_positions.max() + 1 - len(current_input_ids))
        mrope_position_deltas = torch.tensor(mrope_position_deltas, device=input_ids.device).unsqueeze(1)
        return position_ids, mrope_position_deltas

    @accepts_precomputed_kwargs(modality="video")
    @can_return_tuple
    @auto_docstring
    def get_video_features(
            self,
            pixel_values_videos: torch.FloatTensor,
            video_grid_thw: torch.LongTensor | None = None,
            **kwargs: Unpack[TransformersKwargs],
    ) -> tuple | BaseModelOutputWithDeepstackFeatures:
        r"""
        pixel_values_videos (`torch.FloatTensor` of shape `(batch_size, num_channels, image_size, image_size)`):
            The tensors corresponding to the input videos.
        video_grid_thw (`torch.LongTensor` of shape `(num_videos, 3)`, *optional*):
            The temporal, height and width of feature shape of each video in LLM.
        """
        # Same implementation as for images
        return self.get_image_features(pixel_values_videos, video_grid_thw, **kwargs)

    @accepts_precomputed_kwargs(modality="image")
    @can_return_tuple
    @auto_docstring
    def get_image_features(
            self,
            pixel_values: torch.FloatTensor,
            image_grid_thw: torch.LongTensor | None = None,
            **kwargs: Unpack[TransformersKwargs],
    ) -> tuple | BaseModelOutputWithDeepstackFeatures:
        r"""
        pixel_values (`torch.FloatTensor` of shape `(batch_size, num_channels, image_size, image_size)`):
            The tensors corresponding to the input images.
        image_grid_thw (`torch.LongTensor` of shape `(num_images, 3)`, *optional*):
            The temporal, height and width of feature shape of each image in LLM.
        """
        pixel_values = pixel_values.type(self.visual.dtype)
        vision_output: BaseModelOutputWithDeepstackFeatures = self.visual(
            pixel_values, grid_thw=image_grid_thw, return_dict=True, **kwargs
        )
        image_embeds = vision_output.pooler_output
        split_sizes = (image_grid_thw.prod(-1) // self.visual.spatial_merge_size**2).tolist()

        # AQTC: compute per-token saliency as L2 norm of merged vision features
        saliency_scores = torch.norm(image_embeds, p=2, dim=-1)  # (total_tokens,)

        image_embeds = torch.split(image_embeds, split_sizes)
        saliency_list = torch.split(saliency_scores, split_sizes)
        vision_output.pooler_output = image_embeds
        vision_output.saliency = saliency_list

        return vision_output

    def get_placeholder_mask(
            self,
            input_ids: torch.LongTensor,
            inputs_embeds: torch.FloatTensor,
            image_features: torch.FloatTensor | None = None,
            video_features: torch.FloatTensor | None = None,
    ):
        """
        Obtains multimodal placeholder mask from `input_ids` or `inputs_embeds`, and checks that the placeholder token count is
        equal to the length of multimodal features. If the lengths are different, an error is raised.
        """
        if input_ids is None:
            special_image_mask = inputs_embeds == self.get_input_embeddings()(
                torch.tensor(self.config.image_token_id, dtype=torch.long, device=inputs_embeds.device)
            )
            special_image_mask = special_image_mask.all(-1)
            special_video_mask = inputs_embeds == self.get_input_embeddings()(
                torch.tensor(self.config.video_token_id, dtype=torch.long, device=inputs_embeds.device)
            )
            special_video_mask = special_video_mask.all(-1)
        else:
            special_image_mask = input_ids == self.config.image_token_id
            special_video_mask = input_ids == self.config.video_token_id

        n_image_tokens = special_image_mask.sum()
        special_image_mask = special_image_mask.unsqueeze(-1).to(inputs_embeds.device)
        if image_features is not None:
            torch_compilable_check(
                n_image_tokens * inputs_embeds.shape[-1] == image_features.numel(),
                f"Image features and image tokens do not match, tokens: {n_image_tokens}, features: {image_features.shape[0]}",
                )

        n_video_tokens = special_video_mask.sum()
        special_video_mask = special_video_mask.unsqueeze(-1).to(inputs_embeds.device)
        if video_features is not None:
            torch_compilable_check(
                n_video_tokens * inputs_embeds.shape[-1] == video_features.numel(),
                f"Video features and video tokens do not match, tokens: {n_video_tokens}, features: {video_features.shape[0]}",
                )
        return special_image_mask, special_video_mask

    def compute_3d_position_ids(
            self,
            input_ids: torch.Tensor | None,
            inputs_embeds: torch.Tensor | None,
            image_grid_thw: torch.Tensor | None = None,
            video_grid_thw: torch.Tensor | None = None,
            attention_mask: torch.Tensor | None = None,
            past_key_values: torch.Tensor | None = None,
            mm_token_type_ids: torch.IntTensor | None = None,
    ) -> torch.Tensor | None:
        past_key_values_length = 0 if past_key_values is None else past_key_values.get_seq_length()
        has_multimodal = image_grid_thw is not None or video_grid_thw is not None
        if has_multimodal and mm_token_type_ids is None and input_ids is not None:
            raise ValueError(
                "Multimodal data was passed (via `image_grid_thw` or `video_grid_thw`) but `mm_token_type_ids` is "
                "missing. Please pass `mm_token_type_ids` to the model so that multimodal RoPE (M-RoPE) can be "
                "computed correctly. `mm_token_type_ids` is returned by the processor alongside `input_ids`."
            )
        can_compute_mrope = input_ids is not None and mm_token_type_ids is not None and has_multimodal

        if can_compute_mrope and (self.rope_deltas is None or past_key_values_length == 0):
            position_ids, rope_deltas = self.get_rope_index(
                input_ids,
                image_grid_thw=image_grid_thw,
                video_grid_thw=video_grid_thw,
                attention_mask=attention_mask,
                mm_token_type_ids=mm_token_type_ids,
            )
            self.rope_deltas = rope_deltas
        # Use pre-calculated rope-deltas to infer correct 3D position ids during incremental
        # generation (past_key_values_length > 0) or when only inputs_embeds is provided (no input_ids
        # to recompute from). Skip when input_ids is provided without past_key_values to avoid shape
        # mismatches from stale rope_deltas (e.g., training forward pass after generation).
        elif self.rope_deltas is not None and (past_key_values_length > 0 or input_ids is None):
            batch_size, seq_length, _ = inputs_embeds.shape
            if attention_mask is not None:
                position_ids = attention_mask.long().cumsum(-1) - 1
                position_ids = position_ids.masked_fill(attention_mask == 0, 0)
                position_ids = position_ids.view(1, batch_size, -1).repeat(3, 1, 1).to(inputs_embeds.device)
            else:
                position_ids = torch.arange(past_key_values_length, past_key_values_length + seq_length)
                position_ids = position_ids.view(1, 1, -1).expand(3, batch_size, -1).to(inputs_embeds.device)
            delta = self.rope_deltas.repeat_interleave(batch_size // self.rope_deltas.shape[0], dim=0)
            position_ids = position_ids + delta.to(device=inputs_embeds.device)
        else:
            # Can't build correct 3D positions. Let the model infer it
            position_ids = None
        return position_ids
    def _aqtc_compress_visual(
            self,
            visual_embeds: torch.Tensor,
            saliency: torch.Tensor,
            inputs_embeds: torch.Tensor,
            attention_mask: torch.Tensor | None,
            input_ids: torch.LongTensor,
            frame_sizes: list[int] | None = None,
    ) -> tuple[list[list[int]], list[str], torch.Tensor]:
        """Run AQTC compression on concatenated visual tokens.

        When ``frame_sizes`` is provided and ``temporal_aware`` is enabled, the
        compression runs per video-segment with causal novelty precomputation,
        dynamic per-segment budget allocation, and high-novelty token protection
        (aligned with LLaVA-AQTC ``compress_pooled_video_tokens``).

        Returns:
            aqtc_groups: list of groups (local visual index lists) to pool together.
            strategies:   per-group pooling strategy (\"mean\" or \"argmax\").
            importance:   fused importance scores for argmax selection.
        """
        num_tokens = visual_embeds.shape[0]
        device = visual_embeds.device

        # --- Query scores (text→visual cosine similarity) ---
        text_mask = (input_ids != self.config.image_token_id) & (input_ids != self.config.video_token_id)
        if attention_mask is not None:
            text_mask = text_mask & attention_mask.bool()
        text_mask = text_mask.to(inputs_embeds.device)
        text_embeds = inputs_embeds[text_mask]
        if text_embeds.numel() == 0:
            query_scores = visual_embeds.new_zeros(num_tokens)
        else:
            query = text_embeds.float().mean(dim=0, keepdim=True)
            query_scores = F.cosine_similarity(visual_embeds.float(), query.float(), dim=-1).to(
                visual_embeds.dtype
            )

        # --- Importance fusion ---
        saliency_t = saliency.to(device=device, dtype=visual_embeds.dtype)
        importance = self.importance_fusion(query_scores, saliency_t)

        # ------------------------------------------------------------------
        #  Temporal-aware path (aligned with compress_pooled_video_tokens)
        # ------------------------------------------------------------------
        if frame_sizes is not None and self.temporal_aware:
            num_frames = len(frame_sizes)
            if num_frames < 1:
                raise ValueError("frame_sizes must be non-empty when temporal_aware is enabled")

            # Determine spatial tokens per frame (use mode for mixed-size setup)
            spatial_tokens = Counter(frame_sizes).most_common(1)[0][0]

            # Build segment token counts
            segment_sizes = video_segment_sizes(
                num_frames, spatial_tokens, self.novelty_frames_per_segment
            )
            if sum(segment_sizes) != num_tokens:
                # Mixed frame sizes: fall back to flat segmentation by just
                # grouping frame_sizes into novelty_frames_per_segment chunks.
                segment_sizes = []
                seg_frames = 0
                seg_tokens = 0
                for fs in frame_sizes:
                    if seg_frames >= self.novelty_frames_per_segment:
                        segment_sizes.append(seg_tokens)
                        seg_frames = 0
                        seg_tokens = 0
                    seg_frames += 1
                    seg_tokens += fs
                if seg_tokens > 0:
                    segment_sizes.append(seg_tokens)

            num_segments_local = len(segment_sizes)
            global_budget = max(1, int(round(num_tokens * self.keep_ratio)))
            budget_floor = self.keep_ratio * 0.5

            # ---- Precompute novelty causally per segment ----
            self.novelty_estimator.reset()
            precomputed_novelty: list[torch.Tensor] = []
            pre_offset = 0
            for ss in segment_sizes:
                pre_segment = visual_embeds[pre_offset : pre_offset + ss]
                # Per-token coords with correct frame index (t increments per frame)
                pre_coords = [((pre_offset + i) // spatial_tokens, 0, (pre_offset + i) % spatial_tokens)
                              for i in range(ss)] if spatial_tokens > 0 else [(0, 0, i) for i in range(ss)]
                pre_novelty = self.novelty_estimator.score(pre_segment, pre_coords)
                precomputed_novelty.append(pre_novelty)
                # Provisional causal memory
                provisional_n = max(1, int(round(ss * self.keep_ratio)))
                provisional_idx = torch.topk(
                    pre_novelty.float(), k=min(provisional_n, ss), sorted=False
                ).indices
                self.novelty_estimator.update_kept(
                    pre_segment.index_select(0, provisional_idx),
                    [pre_coords[int(i)] for i in provisional_idx.detach().cpu().tolist()],
                )
                pre_offset += ss

            # ---- Dynamic segment budget allocation ----
            seg_keep_ratios: list[float] = [self.keep_ratio] * num_segments_local
            if self.dynamic_segment_budget and num_segments_local > 1:
                importance_cpu = importance.detach().cpu().float()
                seg_imp_means: list[float] = []
                off = 0
                for ss in segment_sizes:
                    seg_imp_means.append(float(importance_cpu[off : off + ss].mean()))
                    off += ss

                imp_min, imp_max = min(seg_imp_means), max(seg_imp_means)
                imp_range = max(imp_max - imp_min, 1e-8)
                imp_norm = [(v - imp_min) / imp_range for v in seg_imp_means]

                if precomputed_novelty:
                    nov_means = [float(n.float().mean().item()) for n in precomputed_novelty]
                    nov_min, nov_max = min(nov_means), max(nov_means)
                    nov_range = max(nov_max - nov_min, 1e-8)
                    nov_norm = [(v - nov_min) / nov_range for v in nov_means]
                    budget_scores = [
                        imp_norm[i] + max(0.0, float(self.temporal_weight)) * nov_norm[i]
                        for i in range(num_segments_local)
                    ]
                    score_min, score_max = min(budget_scores), max(budget_scores)
                    score_range = max(score_max - score_min, 1e-8)
                    budget_norm = [(v - score_min) / score_range for v in budget_scores]
                else:
                    budget_norm = imp_norm

                # Compute per-segment keep_ratios
                for si in range(num_segments_local):
                    s = budget_norm[si]
                    scored_kr = budget_floor + s * (self.budget_ceiling - budget_floor)
                    seg_kr = self.keep_ratio + self.dynamic_budget_strength * (scored_kr - self.keep_ratio)
                    seg_kr = max(budget_floor, min(self.budget_ceiling, seg_kr))
                    seg_keep_ratios[si] = seg_kr

                # Allocate and adjust to global budget
                seg_allocated = []
                total_alloc = 0
                for si, ss in enumerate(segment_sizes):
                    n = int(round(ss * seg_keep_ratios[si]))
                    n = max(1, min(ss, n))
                    seg_allocated.append(n)
                    total_alloc += n

                diff = global_budget - total_alloc
                ordered = sorted(range(num_segments_local), key=lambda i: budget_norm[i], reverse=True)
                if diff > 0:
                    for idx in ordered:
                        if diff <= 0:
                            break
                        ciel = int(segment_sizes[idx] * self.budget_ceiling)
                        add = min(diff, max(0, ciel - seg_allocated[idx]))
                        if add > 0:
                            seg_allocated[idx] += add
                            diff -= add
                elif diff < 0:
                    diff = -diff
                    for idx in reversed(ordered):
                        if diff <= 0:
                            break
                        floor = max(1, int(segment_sizes[idx] * budget_floor))
                        rem = min(diff, max(0, seg_allocated[idx] - floor))
                        if rem > 0:
                            seg_allocated[idx] -= rem
                            diff -= rem

                # Final correction for rounding residual
                residual = global_budget - sum(seg_allocated)
                if residual > 0:
                    for idx in ordered:
                        if residual <= 0:
                            break
                        add = min(residual, segment_sizes[idx] - seg_allocated[idx])
                        seg_allocated[idx] += add
                        residual -= add
                elif residual < 0:
                    residual = -residual
                    for idx in reversed(ordered):
                        if residual <= 0:
                            break
                        rem = min(residual, max(0, seg_allocated[idx] - 1))
                        seg_allocated[idx] -= rem
                        residual -= rem

                seg_keep_ratios = [float(seg_allocated[i]) / float(segment_sizes[i])
                                   for i in range(num_segments_local)]

            # ---- Reset novelty for actual compression pass ----
            self.novelty_estimator.reset()

            # ---- Per-segment four-quadrant planning ----
            all_groups: list[list[int]] = []
            all_strategies: list[str] = []
            offset = 0
            for seg_idx, segment_size in enumerate(segment_sizes):
                seg_slice = slice(offset, offset + segment_size)
                segment = visual_embeds[seg_slice]
                seg_importance = importance[seg_slice]

                # Actual novelty scoring
                seg_coords = [((offset + i) // spatial_tokens, 0, (offset + i) % spatial_tokens)
                              for i in range(segment_size)] if spatial_tokens > 0 else [(0, 0, i) for i in range(segment_size)]
                seg_novelty = self.novelty_estimator.score(segment, seg_coords)

                seg_kr = seg_keep_ratios[seg_idx]
                # Use frame_size only when the frames in this segment all share
                # the same spatial size.  Compute the segment's frame range from
                # cumulative frame_sizes (robust under mixed-size setups).
                seg_frame_size = None
                seg_end = offset + segment_size
                seg_start_frame = 0
                seg_end_frame = 0
                _cum = 0
                for _fi, _fs in enumerate(frame_sizes):
                    if _cum <= offset < _cum + _fs:
                        seg_start_frame = _fi
                    if _cum <= seg_end - 1 < _cum + _fs:
                        seg_end_frame = _fi
                    _cum += _fs
                if seg_start_frame <= seg_end_frame:
                    _sizes_in_seg = frame_sizes[seg_start_frame : seg_end_frame + 1]
                    if _sizes_in_seg and all(s == _sizes_in_seg[0] for s in _sizes_in_seg):
                        seg_frame_size = _sizes_in_seg[0]

                local_groups, _, _, local_strategies = plan_four_quadrant_groups(
                    seg_importance,
                    seg_novelty,
                    keep_ratio=seg_kr,
                    frame_size=seg_frame_size,
                    frame_tolerance=0.03,
                )

                # ---- Temporal protect: preserve high-novelty tokens ----
                if self.temporal_protect_ratio > 0 and local_groups:
                    nov_threshold = torch.quantile(
                        seg_novelty.float(),
                        max(0.0, min(1.0, 1.0 - float(self.temporal_protect_ratio))),
                    )
                    protected = set(
                        int(i) for i in torch.nonzero(
                            seg_novelty >= nov_threshold, as_tuple=False
                        ).flatten().tolist()
                    )
                    for gi, group in enumerate(local_groups):
                        if protected.intersection(group):
                            local_strategies[gi] = "argmax"

                # Offset groups to global visual index space
                for group in local_groups:
                    all_groups.append([idx + offset for idx in group])
                all_strategies.extend(local_strategies)

                # ---- Update novelty memory ----
                if local_groups:
                    pooled_parts = []
                    for group in local_groups:
                        idx = torch.tensor(group, device=device, dtype=torch.long)
                        pooled_parts.append(segment[idx].mean(dim=0, keepdim=True))
                    novelty_pooled = torch.cat(pooled_parts, dim=0)
                    self.novelty_estimator.update_kept(
                        novelty_pooled,
                        [seg_coords[group[0]] for group in local_groups],
                    )

                offset += segment_size

            groups = all_groups
            strategies = all_strategies

            # Store last importance scores
            all_novelty = torch.cat(precomputed_novelty, dim=0) if precomputed_novelty else torch.zeros(num_tokens, device=device, dtype=visual_embeds.dtype)
            self.last_importance_scores = {
                "query": query_scores.detach(),
                "saliency": saliency_t.detach(),
                "novelty": all_novelty.detach(),
                "importance": importance.detach(),
            }

            warn_if_retention_off_target(
                retained=len(groups),
                total=num_tokens,
                keep_ratio=self.keep_ratio,
                tol=0.03,
                context="Qwen3VL-AQTC temporal compress",
            )
            return groups, strategies, importance

        # ------------------------------------------------------------------
        #  Flat path (backward-compatible, no temporal awareness)
        # ------------------------------------------------------------------
        # --- Novelty scores ---
        novelty_scores = self.novelty_estimator(visual_embeds)

        self.last_importance_scores = {
            "query": query_scores.detach(),
            "saliency": saliency_t.detach(),
            "novelty": novelty_scores.detach(),
            "importance": importance.detach(),
        }

        # --- Four-quadrant planning (flat, no spatial constraint) ---
        groups, _covered, _debug, strategies = plan_four_quadrant_groups(
            importance,
            novelty_scores,
            keep_ratio=self.keep_ratio,
            frame_size=None,
            frame_tolerance=0.03,
        )

        # --- Update novelty memory ---
        if groups:
            pooled_parts = []
            for group in groups:
                idx = torch.tensor(group, device=device, dtype=torch.long)
                pooled_parts.append(visual_embeds[idx].mean(dim=0, keepdim=True))
            pooled_for_novelty = torch.cat(pooled_parts, dim=0)
            self.novelty_estimator.update_kept(
                pooled_for_novelty,
                [(0, 0, i) for i in range(len(groups))],
            )

        return groups, strategies, importance

    @staticmethod
    def _aqtc_pool_visual(
            visual_embeds: torch.Tensor,
            groups: list[list[int]],
            strategies: list[str],
            importance: torch.Tensor,
    ) -> torch.Tensor:
        """Pool visual embeddings per AQTC group using the assigned strategy."""
        if not groups:
            return visual_embeds.new_empty((0, visual_embeds.shape[-1]))
        device = visual_embeds.device
        pooled_parts: list[torch.Tensor] = []
        for group, strat in zip(groups, strategies):
            idx = torch.tensor(group, device=device, dtype=torch.long)
            if strat == "argmax":
                best = int(torch.argmax(importance[idx]).item())
                pooled_parts.append(visual_embeds[idx[best]].unsqueeze(0))
            else:
                pooled_parts.append(visual_embeds[idx].mean(dim=0, keepdim=True))
        return torch.cat(pooled_parts, dim=0)

    @staticmethod
    def _aqtc_pool_deepstack(
            deepstack_visual_embeds: list[torch.Tensor] | None,
            groups: list[list[int]],
    ) -> list[torch.Tensor] | None:
        """Mean-pool deepstack features per AQTC group."""
        if deepstack_visual_embeds is None or not groups:
            return deepstack_visual_embeds
        compressed: list[torch.Tensor] = []
        for layer_features in deepstack_visual_embeds:
            device = layer_features.device
            pooled_parts = []
            for group in groups:
                idx = torch.tensor(group, device=device, dtype=torch.long)
                pooled_parts.append(layer_features[idx].mean(dim=0, keepdim=True))
            compressed.append(torch.cat(pooled_parts, dim=0))
        return compressed

    def _aqtc_build_singleton_groups(
            self,
            input_ids: torch.LongTensor,
            visual_pos_masks: torch.Tensor,
            aqtc_groups: list[list[int]],
    ) -> list[list[list[int]]]:
        """Build compression groups where each AQTC group → one singleton at its
        representative (first member's) sequence position.  Non-visual positions
        stay as singleton groups."""
        batch_size = input_ids.shape[0]
        # Find all visual positions: (N_total, 2) → (batch_idx, seq_idx)
        vp = visual_pos_masks.nonzero(as_tuple=False)  # (N, 2)
        # Build a quick lookup: set of representatives' sequence positions per batch
        rep_positions: set[tuple[int, int]] = set()
        for group in aqtc_groups:
            rep = group[0]  # first member is the representative
            if rep < vp.shape[0]:
                rep_positions.add((int(vp[rep, 0].item()), int(vp[rep, 1].item())))

        groups: list[list[list[int]]] = []
        for batch_idx in range(batch_size):
            batch_groups: list[list[int]] = []
            for seq_idx in range(input_ids.shape[1]):
                is_visual = bool(visual_pos_masks[batch_idx, seq_idx].item())
                if is_visual:
                    # Only keep representative positions; others are excluded
                    if (batch_idx, seq_idx) in rep_positions:
                        batch_groups.append([seq_idx])
                    # else: dropped (pooled into representative)
                else:
                    batch_groups.append([seq_idx])
            groups.append(batch_groups)
        return groups

    def _build_sequence_keep_mask(
            self,
            input_ids: torch.LongTensor,
            image_selected_mask: torch.Tensor | None = None,
            video_selected_mask: torch.Tensor | None = None,
    ):
        keep_mask = torch.ones_like(input_ids, dtype=torch.bool)
        if image_selected_mask is not None:
            image_coords = (input_ids == self.config.image_token_id).nonzero(as_tuple=True)
            if image_coords[0].shape[0] != image_selected_mask.shape[0]:
                raise ValueError(
                    f"Image keep mask mismatch: placeholders={image_coords[0].shape[0]}, selected={image_selected_mask.shape[0]}"
                )
            keep_mask[image_coords] = image_selected_mask.to(keep_mask.device)
        if video_selected_mask is not None:
            video_coords = (input_ids == self.config.video_token_id).nonzero(as_tuple=True)
            if video_coords[0].shape[0] != video_selected_mask.shape[0]:
                raise ValueError(
                    f"Video keep mask mismatch: placeholders={video_coords[0].shape[0]}, selected={video_selected_mask.shape[0]}"
                )
            keep_mask[video_coords] = video_selected_mask.to(keep_mask.device)
        return keep_mask

    def _build_compression_groups(
            self,
            input_ids: torch.LongTensor,
            visual_pos_masks: torch.Tensor,
            image_selected_mask: torch.Tensor | None = None,
            video_selected_mask: torch.Tensor | None = None,
            save_redundancy: bool = False,
    ):
        """Build output-to-input groups for visual-token compression.

        A selected visual token stays as a singleton. A contiguous run of
        unselected visual tokens becomes one group and is mean-pooled later.
        """
        batch_size = input_ids.shape[0]
        image_selected_mask = (
            image_selected_mask.to(input_ids.device) if image_selected_mask is not None else None
        )
        video_selected_mask = (
            video_selected_mask.to(input_ids.device) if video_selected_mask is not None else None
        )
        groups = []
        image_offset = 0
        video_offset = 0
        for batch_idx in range(batch_size):
            batch_groups = []
            visual_run = []
            visual_run_selected = []
            visual_run_types = []

            def flush_visual_run():
                if not visual_run:
                    return
                if all(visual_run_selected):
                    batch_groups.extend(([pos] for pos in visual_run))
                else:
                    # Preserve selected tokens and pool each contiguous
                    # unselected run independently.
                    start = 0
                    while start < len(visual_run):
                        if visual_run_selected[start]:
                            batch_groups.append([visual_run[start]])
                            start += 1
                            continue
                        end = start + 1
                        while end < len(visual_run) and not visual_run_selected[end]:
                            end += 1
                        run_length = end - start
                        if run_length > 1 or save_redundancy:
                            batch_groups.append(visual_run[start:end])
                        start = end
                visual_run.clear()
                visual_run_selected.clear()
                visual_run_types.clear()

            for seq_idx in range(input_ids.shape[1]):
                is_visual = bool(visual_pos_masks[batch_idx, seq_idx].item())
                if not is_visual:
                    flush_visual_run()
                    batch_groups.append([seq_idx])
                    continue

                token_id = int(input_ids[batch_idx, seq_idx].item())
                if token_id == self.config.image_token_id:
                    visual_type = "image"
                    if image_selected_mask is None:
                        selected = True
                    else:
                        selected = bool(image_selected_mask[image_offset].item())
                    image_offset += 1
                elif token_id == self.config.video_token_id:
                    visual_type = "video"
                    if video_selected_mask is None:
                        selected = True
                    else:
                        selected = bool(video_selected_mask[video_offset].item())
                    video_offset += 1
                else:
                    visual_type = "other"
                    selected = True
                if visual_run_types and visual_run_types[-1] != visual_type:
                    flush_visual_run()
                visual_run.append(seq_idx)
                visual_run_selected.append(selected)
                visual_run_types.append(visual_type)
            flush_visual_run()
            groups.append(batch_groups)

        if image_selected_mask is not None and image_offset != image_selected_mask.numel():
            raise ValueError("Image selected mask was not fully consumed while building compression groups")
        if video_selected_mask is not None and video_offset != video_selected_mask.numel():
            raise ValueError("Video selected mask was not fully consumed while building compression groups")
        return groups

    def _compress_sequence(
            self,
            inputs_embeds: torch.Tensor,
            attention_mask: torch.Tensor | None,
            position_ids: torch.Tensor | None,
            visual_pos_masks: torch.Tensor | None,
            deepstack_visual_embeds: list[torch.Tensor] | None,
            compression_groups: list[list[list[int]]],
    ):
        """Pool each compression group and rebuild all aligned sequence tensors."""
        batch_size = inputs_embeds.shape[0]
        lengths = torch.tensor(
            [len(batch_groups) for batch_groups in compression_groups],
            device=inputs_embeds.device,
            dtype=torch.long,
        )
        max_length = int(lengths.max().item())
        hidden_size = inputs_embeds.shape[-1]
        compressed_inputs = inputs_embeds.new_zeros(batch_size, max_length, hidden_size)
        compressed_attention = attention_mask.new_zeros(batch_size, max_length) if attention_mask is not None else None
        compressed_visual = visual_pos_masks.new_zeros(batch_size, max_length) if visual_pos_masks is not None else None

        compressed_position = None
        if position_ids is not None:
            if position_ids.dim() == 3:
                compressed_position = position_ids.new_zeros(position_ids.shape[0], batch_size, max_length)
            else:
                compressed_position = position_ids.new_zeros(batch_size, max_length)

        visual_offsets = None
        if visual_pos_masks is not None:
            visual_counts = visual_pos_masks.sum(dim=1).to(inputs_embeds.device)
            visual_offsets = torch.cat(
                [visual_counts.new_zeros(1), visual_counts.cumsum(dim=0)[:-1]], dim=0
            )
        compressed_deepstack = None
        if deepstack_visual_embeds is not None and visual_pos_masks is not None:
            compressed_deepstack = [[] for _ in deepstack_visual_embeds]

        for batch_idx, batch_groups in enumerate(compression_groups):
            for output_idx, group in enumerate(batch_groups):
                group_tensor = torch.tensor(group, device=inputs_embeds.device, dtype=torch.long)
                compressed_inputs[batch_idx, output_idx] = inputs_embeds[batch_idx, group_tensor].mean(dim=0)
                is_visual_group = bool(visual_pos_masks[batch_idx, group[0]].item()) if visual_pos_masks is not None else False
                if compressed_attention is not None:
                    if is_visual_group:
                        # A retained singleton or pooled visual token must stay active
                        # even when its source placeholders were masked during selection.
                        compressed_attention[batch_idx, output_idx] = 1
                    else:
                        compressed_attention[batch_idx, output_idx] = attention_mask[
                            batch_idx, group_tensor.to(attention_mask.device)
                        ].max()
                if compressed_visual is not None:
                    compressed_visual[batch_idx, output_idx] = is_visual_group
                if compressed_position is not None:
                    if compressed_position.dim() == 3:
                        compressed_position[:, batch_idx, output_idx] = position_ids[:, batch_idx, group[0]]
                    else:
                        compressed_position[batch_idx, output_idx] = position_ids[batch_idx, group[0]]

                if is_visual_group and compressed_deepstack is not None:
                    # Use the visual rank of every source sequence position;
                    # this remains correct when singleton redundancy is dropped.
                    original_visual_indices = torch.stack([
                        int(visual_offsets[batch_idx].item())
                        + visual_pos_masks[batch_idx, : original_idx + 1].sum()
                        - 1
                        for original_idx in group
                    ]).long()
                    index_tensor = original_visual_indices
                    for layer_idx, features in enumerate(deepstack_visual_embeds):
                        compressed_deepstack[layer_idx].append(features[index_tensor.to(features.device)].mean(dim=0))

        if compressed_deepstack is not None:
            compressed_deepstack = [
                torch.stack(layer_features, dim=0) if layer_features else features.new_empty((0, features.shape[-1]))
                for layer_features, features in zip(compressed_deepstack, deepstack_visual_embeds)
            ]
        return compressed_inputs, compressed_attention, compressed_position, compressed_visual, compressed_deepstack

    def _select_deepstack_features(
            self,
            deepstack_visual_embeds: list[torch.Tensor] | None,
            visual_pos_masks: torch.Tensor | None,
            sequence_keep_mask: torch.Tensor,
    ):
        if deepstack_visual_embeds is None or visual_pos_masks is None:
            return deepstack_visual_embeds
        visual_keep_mask = sequence_keep_mask[visual_pos_masks.to(sequence_keep_mask.device)].to(deepstack_visual_embeds[0].device)
        return [features[visual_keep_mask] for features in deepstack_visual_embeds]

    def _prune_sequence(
            self,
            inputs_embeds: torch.Tensor,
            attention_mask: torch.Tensor | None,
            position_ids: torch.Tensor | None,
            visual_pos_masks: torch.Tensor | None,
            sequence_keep_mask: torch.Tensor,
    ):
        batch_size = inputs_embeds.shape[0]
        lengths = sequence_keep_mask.sum(dim=1)#每个 batch 实际保留了多少个 Token
        max_length = int(lengths.max().item())

        pruned_inputs_embeds = inputs_embeds.new_zeros(batch_size, max_length, inputs_embeds.shape[-1])
        pruned_attention_mask = None
        if attention_mask is not None:
            pruned_attention_mask = attention_mask.new_zeros(batch_size, max_length)
        pruned_visual_pos_masks = None
        if visual_pos_masks is not None:
            pruned_visual_pos_masks = visual_pos_masks.new_zeros(batch_size, max_length)

        position_prefix = None
        pruned_position_ids = None
        if position_ids is not None:
            if position_ids.dim() == 3:
                position_prefix = position_ids.shape[0]
                pruned_position_ids = position_ids.new_zeros(position_prefix, batch_size, max_length)
            else:
                pruned_position_ids = position_ids.new_zeros(batch_size, max_length)

        for batch_idx in range(batch_size):
            keep = sequence_keep_mask[batch_idx].to(inputs_embeds.device)
            length = int(lengths[batch_idx].item())
            pruned_inputs_embeds[batch_idx, :length] = inputs_embeds[batch_idx, keep]
            if attention_mask is not None:
                pruned_attention_mask[batch_idx, :length] = attention_mask[batch_idx, keep.to(attention_mask.device)]
            if visual_pos_masks is not None:
                pruned_visual_pos_masks[batch_idx, :length] = visual_pos_masks[
                    batch_idx, keep.to(visual_pos_masks.device)
                ]
            if position_ids is not None:
                if position_ids.dim() == 3:
                    pruned_position_ids[:, batch_idx, :length] = position_ids[
                        :, batch_idx, keep.to(position_ids.device)
                    ]
                else:
                    pruned_position_ids[batch_idx, :length] = position_ids[batch_idx, keep.to(position_ids.device)]

        return pruned_inputs_embeds, pruned_attention_mask, pruned_position_ids, pruned_visual_pos_masks

    def token_L2_select(self,image_embeds,attention_mask,input_ids):
        N_total = image_embeds.shape[0]
        K_select = N_total // 2  # 假设保留一半
        # 计算每个 Token 的 L2 范数（向量的长度），范数越大代表特征越“活跃”
        scores = torch.norm(image_embeds, p=2, dim=-1)
        # 或者使用“与全局均值的差异”（类似方差的概念），差异越大越重要
        # global_mean = image_embeds.mean(dim=0, keepdim=True)
        # scores = torch.norm(image_embeds - global_mean, p=2, dim=-1)
        # 选出得分最高的 K 个 Token 的索引
        top_k_indices = torch.topk(scores, k=K_select, largest=True).indices
        selected_mask = torch.zeros(N_total, dtype=torch.bool, device=image_embeds.device)
        selected_mask[top_k_indices] = True
        # 将未被选中的 token embedding 置为 0
        if attention_mask is not None:
            # ==========================================
            # 🟢 正确做法：直接从 input_ids 中定位 Visual Tokens
            # ==========================================
            # 1. 找到 input_ids 中所有属于 image 或 video token 的位置
            # 形状为 (batch_size, seq_len) 的 bool 张量
            is_visual_token = (input_ids == self.config.image_token_id) | (input_ids == self.config.video_token_id)

            # 2. 获取这些 visual token 的 2D 坐标 (batch_idx, seq_idx)
            # 此时 visual_coords 是一个包含 2 个 tensor 的 tuple，长度正好等于 visual token 的总数
            visual_coords = is_visual_token.nonzero(as_tuple=True)
            bsz_idx, seq_idx = visual_coords

            # 3. 校验 selected_mask 的长度是否匹配 (防御性编程)
            num_visual_tokens = bsz_idx.shape[0]
            assert selected_mask.shape[0] == num_visual_tokens, \
                f"selected_mask 长度 ({selected_mask.shape[0]}) 与 visual token 数量 ({num_visual_tokens}) 不匹配！"

            unselected_mask = ~selected_mask

            # 5. 提取出需要被屏蔽的坐标
            invalid_bsz = bsz_idx[unselected_mask.to(bsz_idx.device)]
            invalid_seq = seq_idx[unselected_mask.to(bsz_idx.device)]

            # 6. 将 attention_mask 中对应位置的值设为 0 (在 Qwen 中 0 表示 ignore/pad)
            # 这样在 Attention 计算时，这些被剔除的 visual token 就不会参与计算，也不会影响其他 token
            attention_mask[invalid_bsz, invalid_seq] = 0
        return selected_mask,attention_mask

    def text_guided_cross_attention(self,image_embeds,inputs_embeds,attention_mask,input_ids):
        query = inputs_embeds.squeeze(dim=0).mean(dim=0, keepdim=True)
        scores = F.cosine_similarity(image_embeds, query, dim=-1)
        N_total = image_embeds.shape[0]
        K_select = N_total // 2
        top_k_indices = torch.topk(scores, k=K_select, largest=True).indices
        selected_mask = torch.zeros(N_total, dtype=torch.bool, device=image_embeds.device)
        selected_mask[top_k_indices] = True
        if attention_mask is not None:
            is_visual_token = (input_ids == self.config.image_token_id) | (input_ids == self.config.video_token_id)

            visual_coords = is_visual_token.nonzero(as_tuple=True)
            bsz_idx, seq_idx = visual_coords

            num_visual_tokens = bsz_idx.shape[0]
            assert selected_mask.shape[0] == num_visual_tokens, \
                f"selected_mask 长度 ({selected_mask.shape[0]}) 与 visual token 数量 ({num_visual_tokens}) 不匹配！"

            unselected_mask = ~selected_mask
            invalid_bsz = bsz_idx[unselected_mask.to(bsz_idx.device)]
            invalid_seq = seq_idx[unselected_mask.to(bsz_idx.device)]

            attention_mask[invalid_bsz, invalid_seq] = 0
        return selected_mask,attention_mask

    def grid_based_top_K(self,image_embeds,attention_mask,input_ids,image_grid_thw):
        N_total = image_embeds.shape[0]
        K_select = N_total // 2

        # 假设当前 batch 只有一张图，它的 grid_thw 是 [t, h, w]
        # 经过 Merger 压缩后，实际的 3D 网格大小是 [t, h/2, w/2]
        t, h, w = image_grid_thw[0][0].item(), image_grid_thw[0][1].item(), image_grid_thw[0][2].item()
        merge_size = self.config.vision_config.spatial_merge_size  # 通常是 2
        llm_h, llm_w = h // merge_size, w // merge_size


        image_grid = image_embeds.view(llm_h, llm_w, -1)

        # 2. 将网格分成 2x2 的四个大区块 (Block)
        block_h, block_w = llm_h // 2, llm_w // 2
        blocks = image_grid.unfold(0, block_h, block_h).unfold(1, block_w, block_w)
        # blocks shape: [2, 2, block_h, block_w, hidden_size]

        # 3. 在每个区块内部，计算得分 (这里用 L2 范数举例)
        # 将区块展平以便计算: [4, block_h*block_w, hidden_size]
        blocks_flat = blocks.contiguous().view(4, -1, image_embeds.shape[-1])
        block_scores = torch.norm(blocks_flat, p=2, dim=-1)  # [4, block_h*block_w]

        # 4. 在每个区块内选 Top-K/4 个
        k_per_block = K_select // 4
        block_topk_indices = torch.topk(block_scores, k=k_per_block, largest=True).indices  # [4, k_per_block]

        # 5. 将区块内的局部索引，还原回全局的 1D 索引
        block_offsets_2d = [
            (0, 0),  # block 0: 左上区块
            (0, block_w),  # block 1: 右上区块
            (block_h, 0),  # block 2: 左下区块
            (block_h, block_w)  # block 3: 右下区块
        ]
        top_k_indices = []

        for block_id in range(4):
            # 当前区块内筛选出的局部一维索引 [k_per_block,]
            local_1d_idx = block_topk_indices[block_id]
            # 区块左上角二维偏移
            off_h, off_w = block_offsets_2d[block_id]

            # 局部1D索引还原为区块内局部二维坐标 (local_h, local_w)
            local_h = local_1d_idx // block_w
            local_w = local_1d_idx % block_w

            # 叠加区块偏移，得到全局完整网格下的二维坐标
            global_h = local_h + off_h
            global_w = local_w + off_w

            # 全局二维坐标映射回全局一维索引 (行优先平铺)
            global_1d_idx = global_h * llm_w + global_w
            top_k_indices.append(global_1d_idx)

        # 拼接4个区块选出的全部全局索引
        top_k_indices = torch.cat(top_k_indices, dim=0)
        # 最终得到全局的 top_k_indices

        # 6. 生成 mask
        selected_mask = torch.zeros(N_total, dtype=torch.bool, device=image_embeds.device)
        selected_mask[top_k_indices] = True
        if attention_mask is not None:
            # ==========================================
            # 🟢 正确做法：直接从 input_ids 中定位 Visual Tokens
            # ==========================================
            # 1. 找到 input_ids 中所有属于 image 或 video token 的位置
            # 形状为 (batch_size, seq_len) 的 bool 张量
            is_visual_token = (input_ids == self.config.image_token_id) | (input_ids == self.config.video_token_id)

            # 2. 获取这些 visual token 的 2D 坐标 (batch_idx, seq_idx)
            # 此时 visual_coords 是一个包含 2 个 tensor 的 tuple，长度正好等于 visual token 的总数
            visual_coords = is_visual_token.nonzero(as_tuple=True)
            bsz_idx, seq_idx = visual_coords

            # 3. 校验 selected_mask 的长度是否匹配 (防御性编程)
            num_visual_tokens = bsz_idx.shape[0]
            assert selected_mask.shape[0] == num_visual_tokens, \
                f"selected_mask 长度 ({selected_mask.shape[0]}) 与 visual token 数量 ({num_visual_tokens}) 不匹配！"

            unselected_mask = ~selected_mask

            # 5. 提取出需要被屏蔽的坐标
            invalid_bsz = bsz_idx[unselected_mask.to(bsz_idx.device)]
            invalid_seq = seq_idx[unselected_mask.to(bsz_idx.device)]

            # 6. 将 attention_mask 中对应位置的值设为 0 (在 Qwen 中 0 表示 ignore/pad)
            # 这样在 Attention 计算时，这些被剔除的 visual token 就不会参与计算，也不会影响其他 token
            attention_mask[invalid_bsz, invalid_seq] = 0
        return selected_mask,attention_mask

    @auto_docstring
    @can_return_tuple
    def forward(
            self,
            input_ids: torch.LongTensor = None,
            attention_mask: torch.Tensor | None = None,
            position_ids: torch.LongTensor | None = None,
            past_key_values: Cache | None = None,
            inputs_embeds: torch.FloatTensor | None = None,
            pixel_values: torch.Tensor | None = None,
            pixel_values_videos: torch.FloatTensor | None = None,
            image_grid_thw: torch.LongTensor | None = None,
            video_grid_thw: torch.LongTensor | None = None,
            mm_token_type_ids: torch.IntTensor | None = None,
            **kwargs: Unpack[TransformersKwargs],
    ) -> tuple | Qwen3VLModelOutputWithPast:
        r"""
        image_grid_thw (`torch.LongTensor` of shape `(num_images, 3)`, *optional*):
            The temporal, height and width of feature shape of each image in LLM.
        video_grid_thw (`torch.LongTensor` of shape `(num_videos, 3)`, *optional*):
            The temporal, height and width of feature shape of each video in LLM.
        """
        if (input_ids is None) ^ (inputs_embeds is not None):
            raise ValueError("You must specify exactly one of input_ids or inputs_embeds")

        if inputs_embeds is None:
            inputs_embeds = self.get_input_embeddings()(input_ids)

        image_mask = None
        video_mask = None
        # Collect concatenated visual embeds + saliency for unified AQTC compression
        all_visual_embeds: list[torch.Tensor] = []
        all_saliency: list[torch.Tensor] = []

        if pixel_values is not None:
            image_outputs: BaseModelOutputWithDeepstackFeatures = self.get_image_features(
                pixel_values, image_grid_thw, return_dict=True, **kwargs
            )
            image_embeds_flat = torch.cat(image_outputs.pooler_output, dim=0).to(inputs_embeds.device, inputs_embeds.dtype)
            image_saliency_flat = torch.cat(image_outputs.saliency, dim=0)
            deepstack_image_embeds = image_outputs.deepstack_features

            image_mask, _ = self.get_placeholder_mask(
                input_ids, inputs_embeds=inputs_embeds, image_features=image_embeds_flat
            )
            inputs_embeds = inputs_embeds.masked_scatter(image_mask, image_embeds_flat)
            all_visual_embeds.append(image_embeds_flat)
            all_saliency.append(image_saliency_flat)

        if pixel_values_videos is not None:
            video_outputs: BaseModelOutputWithDeepstackFeatures = self.get_video_features(
                pixel_values_videos, video_grid_thw, return_dict=True, **kwargs
            )
            video_embeds_flat = torch.cat(video_outputs.pooler_output, dim=0).to(inputs_embeds.device, inputs_embeds.dtype)
            video_saliency_flat = torch.cat(video_outputs.saliency, dim=0)
            deepstack_video_embeds = video_outputs.deepstack_features
            _, video_mask = self.get_placeholder_mask(
                input_ids, inputs_embeds=inputs_embeds, video_features=video_embeds_flat
            )
            inputs_embeds = inputs_embeds.masked_scatter(video_mask, video_embeds_flat)
            all_visual_embeds.append(video_embeds_flat)
            all_saliency.append(video_saliency_flat)

        # Merge masks and deepstack (same as before, but without selected_mask)
        visual_pos_masks = None
        deepstack_visual_embeds = None
        if image_mask is not None and video_mask is not None:
            image_mask = image_mask[..., 0]
            video_mask = video_mask[..., 0]
            visual_pos_masks = image_mask | video_mask
            deepstack_visual_embeds = []
            image_mask_joint = image_mask[visual_pos_masks]
            video_mask_joint = video_mask[visual_pos_masks]
            for img_embed, vid_embed in zip(deepstack_image_embeds, deepstack_video_embeds):
                embed_joint = img_embed.new_zeros(visual_pos_masks.sum(), img_embed.shape[-1]).to(img_embed.device)
                embed_joint[image_mask_joint, :] = img_embed
                embed_joint[video_mask_joint, :] = vid_embed
                deepstack_visual_embeds.append(embed_joint)
        elif image_mask is not None:
            image_mask = image_mask[..., 0]
            visual_pos_masks = image_mask
            deepstack_visual_embeds = deepstack_image_embeds
        elif video_mask is not None:
            video_mask = video_mask[..., 0]
            visual_pos_masks = video_mask
            deepstack_visual_embeds = deepstack_video_embeds

        if position_ids is None:
            position_ids = self.compute_3d_position_ids(
                input_ids=input_ids,
                image_grid_thw=image_grid_thw,
                video_grid_thw=video_grid_thw,
                inputs_embeds=inputs_embeds,
                attention_mask=attention_mask,
                past_key_values=past_key_values,
                mm_token_type_ids=mm_token_type_ids,
            )

        # --- AQTC visual-token compression ---
        if all_visual_embeds and visual_pos_masks is not None:
            visual_embeds_cat = torch.cat(all_visual_embeds, dim=0)
            saliency_cat = torch.cat(all_saliency, dim=0)

            # Compute frame_sizes for temporal-aware compression.
            # Each grid_thw row is (T, H, W); for videos T may be > 1
            # and must be split into per-frame token counts that match
            # the exact split_sizes used by get_image_features.
            merge_sq = self.visual.spatial_merge_size ** 2
            frame_sizes: list[int] = []

            def _append_frame_sizes(grid_thw):
                for row in grid_thw:
                    t, h, w = int(row[0].item()), int(row[1].item()), int(row[2].item())
                    total = t * h * w // merge_sq
                    if t == 1:
                        frame_sizes.append(total)
                    else:
                        base = total // t
                        rem = total % t
                        frame_sizes.extend([base + 1] * rem + [base] * (t - rem))

            if image_grid_thw is not None:
                _append_frame_sizes(image_grid_thw)
            if video_grid_thw is not None:
                _append_frame_sizes(video_grid_thw)

            # Track pre-compression stats
            original_visual_tokens = int(visual_embeds_cat.shape[0])
            if attention_mask is not None:
                original_prefill_tokens = int(attention_mask.sum().item())
            else:
                original_prefill_tokens = int(inputs_embeds.shape[0] * inputs_embeds.shape[1])

            # 1) AQTC: compute scores + four-quadrant groups
            aqtc_groups, aqtc_strategies, aqtc_importance = self._aqtc_compress_visual(
                visual_embeds_cat, saliency_cat, inputs_embeds, attention_mask, input_ids,
                frame_sizes=frame_sizes,
            )

            # 2) Pre-pool visual embeddings and write back to representative positions
            visual_from_seq = inputs_embeds[visual_pos_masks]
            compressed_visual = self._aqtc_pool_visual(
                visual_from_seq, aqtc_groups, aqtc_strategies, aqtc_importance
            )
            vp = visual_pos_masks.nonzero(as_tuple=False)  # (N_total, 2) → (batch, seq)
            for gi, group in enumerate(aqtc_groups):
                if group:
                    rep_pos = vp[group[0]]
                    inputs_embeds[rep_pos[0], rep_pos[1]] = compressed_visual[gi]

            # 3) Pre-pool deepstack
            compressed_deepstack = self._aqtc_pool_deepstack(deepstack_visual_embeds, aqtc_groups)

            # 4) Build singleton compression groups (each AQTC group → one output position)
            compression_groups = self._aqtc_build_singleton_groups(
                input_ids, visual_pos_masks, aqtc_groups
            )

            # 5) Compress sequence (pre-pooled tokens → _compress_sequence just copies singletons)
            (inputs_embeds, attention_mask, position_ids, visual_pos_masks, _,
             ) = self._compress_sequence(
                inputs_embeds, attention_mask, position_ids,
                visual_pos_masks, None, compression_groups,
            )
            deepstack_visual_embeds = compressed_deepstack

            # Track post-compression stats
            if attention_mask is not None:
                compressed_prefill_tokens = int(attention_mask.sum().item())
            else:
                compressed_prefill_tokens = int(inputs_embeds.shape[0] * inputs_embeds.shape[1])
            compressed_visual_tokens_count = (
                int(visual_pos_masks.sum().item()) if visual_pos_masks is not None else 0
            )
            self.total_original_prefill_tokens += original_prefill_tokens
            self.total_compressed_prefill_tokens += compressed_prefill_tokens
            self.total_original_visual_tokens += original_visual_tokens
            self.total_compressed_visual_tokens += compressed_visual_tokens_count

        outputs = self.language_model(
            input_ids=None,
            position_ids=position_ids,
            attention_mask=attention_mask,
            past_key_values=past_key_values,
            inputs_embeds=inputs_embeds,
            visual_pos_masks=visual_pos_masks,
            deepstack_visual_embeds=deepstack_visual_embeds,
            **kwargs,
        )

        return Qwen3VLModelOutputWithPast(
            **outputs,
            rope_deltas=self.rope_deltas,
        )


@auto_docstring
@dataclass
class Qwen3VLCausalLMOutputWithPast(CausalLMOutputWithPast):
    r"""
    rope_deltas (`torch.LongTensor` of shape `(batch_size, )`, *optional*):
        The rope index difference between sequence length and multimodal rope.
        The attribute is deprecated and will be removed in v5.20, use `model.base_model.rope_deltas` instead.
    """

    rope_deltas: torch.LongTensor | None = None


class Qwen3VLForConditionalGeneration(Qwen3VLPreTrainedModel, GenerationMixin):
    """
    Args:
        save_redundancy (`bool`, *optional*, defaults to `False`):
            Whether to retain singleton unselected visual tokens.
        keep_ratio (`float`, *optional*, defaults to 0.75):
            Target fraction of visual tokens to retain (AQTC four-quadrant).
        memory_capacity (`int`, *optional*, defaults to 256):
            Maximum number of compressed visual tokens stored as novelty history.
        query_weight (`float`, *optional*, defaults to 0.4):
            Weight of query relevance in the AQTC importance fusion.
        saliency_weight (`float`, *optional*, defaults to 0.3):
            Weight of visual saliency in the AQTC importance fusion.
        novelty_frames_per_segment (`int`, *optional*, defaults to 4):
            Frames per novelty/compression segment.
        dynamic_segment_budget (`bool`, *optional*, defaults to `False`):
            Enable per-segment variable keep_ratio allocation.
        dynamic_budget_strength (`float`, *optional*, defaults to 0.5):
            Strength of dynamic budget deviation from base keep_ratio.
        budget_ceiling (`float`, *optional*, defaults to 0.45):
            Maximum keep_ratio any segment can receive.
        temporal_aware (`bool`, *optional*, defaults to `False`):
            Enable temporal-aware novelty precomputation with causal memory.
        temporal_weight (`float`, *optional*, defaults to 0.2):
            Weight of temporal novelty in dynamic segment budget allocation.
        temporal_protect_ratio (`float`, *optional*, defaults to 0.15):
            Fraction of high-novelty tokens protected via argmax override.
    """
    _tied_weights_keys = {"lm_head.weight": "model.language_model.embed_tokens.weight"}
    # Reference: fix gemma3 grad acc #37208
    accepts_loss_kwargs = False

    def __init__(
            self,
            config,
            save_redundancy: bool = False,
            keep_ratio: float = 0.75,
            memory_capacity: int = 256,
            query_weight: float = 0.4,
            saliency_weight: float = 0.3,
            novelty_frames_per_segment: int = 4,
            dynamic_segment_budget: bool = False,
            dynamic_budget_strength: float = 0.5,
            budget_ceiling: float = 0.45,
            temporal_aware: bool = False,
            temporal_weight: float = 0.2,
            temporal_protect_ratio: float = 0.15,
    ):
        """Build the causal language model with AQTC visual-token compression settings.

        Args:
            save_redundancy (`bool`, *optional*, defaults to `False`):
                Whether to retain singleton unselected visual tokens.
            keep_ratio (`float`, *optional*, defaults to 0.75):
                Target fraction of visual tokens to retain.
            memory_capacity (`int`, *optional*, defaults to 256):
                Maximum number of compressed visual tokens stored as novelty history.
            query_weight (`float`, *optional*, defaults to 0.4):
                Weight of query relevance in importance fusion.
            saliency_weight (`float`, *optional*, defaults to 0.3):
                Weight of visual saliency in importance fusion.
            novelty_frames_per_segment (`int`, *optional*, defaults to 4):
                Frames per novelty/compression segment.
            dynamic_segment_budget (`bool`, *optional*, defaults to `False`):
                Enable per-segment variable budget.
            dynamic_budget_strength (`float`, *optional*, defaults to 0.5):
                Strength of dynamic budget deviation.
            budget_ceiling (`float`, *optional*, defaults to 0.45):
                Maximum keep_ratio per segment.
            temporal_aware (`bool`, *optional*, defaults to `False`):
                Enable temporal-aware novelty with causal memory.
            temporal_weight (`float`, *optional*, defaults to 0.2):
                Weight of temporal novelty in budget allocation.
            temporal_protect_ratio (`float`, *optional*, defaults to 0.15):
                Fraction of high-novelty tokens to protect.
        """
        super().__init__(config)
        self.save_redundancy = save_redundancy
        self.model = Qwen3VLModel(
            config,
            save_redundancy=save_redundancy,
            keep_ratio=keep_ratio,
            memory_capacity=memory_capacity,
            query_weight=query_weight,
            saliency_weight=saliency_weight,
            novelty_frames_per_segment=novelty_frames_per_segment,
            dynamic_segment_budget=dynamic_segment_budget,
            dynamic_budget_strength=dynamic_budget_strength,
            budget_ceiling=budget_ceiling,
            temporal_aware=temporal_aware,
            temporal_weight=temporal_weight,
            temporal_protect_ratio=temporal_protect_ratio,
        )
        self.lm_head = nn.Linear(config.text_config.hidden_size, config.text_config.vocab_size, bias=False)

        self.post_init()

    def reset_novelty_memory(self) -> None:
        """Clear visual history before processing an unrelated video."""
        self.model.reset_novelty_memory()

    def reset_token_stats(self) -> None:
        self.model.total_original_prefill_tokens = 0
        self.model.total_compressed_prefill_tokens = 0
        self.model.total_original_visual_tokens = 0
        self.model.total_compressed_visual_tokens = 0

    def get_token_stats(self) -> dict:
        return {
            "original_prefill": self.model.total_original_prefill_tokens,
            "compressed_prefill": self.model.total_compressed_prefill_tokens,
            "original_visual": self.model.total_original_visual_tokens,
            "compressed_visual": self.model.total_compressed_visual_tokens,
        }

    def get_last_importance_scores(self) -> dict[str, torch.Tensor] | None:
        """Return score components from the latest visual selection."""
        return self.model.get_last_importance_scores()

    @auto_docstring
    def get_video_features(
            self,
            pixel_values_videos: torch.FloatTensor,
            video_grid_thw: torch.LongTensor | None = None,
            **kwargs: Unpack[TransformersKwargs],
    ) -> tuple | BaseModelOutputWithDeepstackFeatures:
        r"""
        pixel_values_videos (`torch.FloatTensor` of shape `(batch_size, num_channels, image_size, image_size)`):
            The tensors corresponding to the input videos.
        video_grid_thw (`torch.LongTensor` of shape `(num_videos, 3)`, *optional*):
            The temporal, height and width of feature shape of each video in LLM.
        """
        return self.model.get_video_features(pixel_values_videos, video_grid_thw, **kwargs)

    @auto_docstring
    def get_image_features(
            self,
            pixel_values: torch.FloatTensor,
            image_grid_thw: torch.LongTensor | None = None,
            **kwargs: Unpack[TransformersKwargs],
    ) -> tuple | BaseModelOutputWithDeepstackFeatures:
        r"""
        pixel_values (`torch.FloatTensor` of shape `(batch_size, num_channels, image_size, image_size)`):
            The tensors corresponding to the input images.
        image_grid_thw (`torch.LongTensor` of shape `(num_images, 3)`, *optional*):
            The temporal, height and width of feature shape of each image in LLM.
        """
        return self.model.get_image_features(pixel_values, image_grid_thw, **kwargs)

    @can_return_tuple
    def forward(
            self,
            input_ids: torch.LongTensor = None,
            attention_mask: torch.Tensor | None = None,
            position_ids: torch.LongTensor | None = None,
            past_key_values: Cache | None = None,
            inputs_embeds: torch.FloatTensor | None = None,
            labels: torch.LongTensor | None = None,
            pixel_values: torch.Tensor | None = None,
            pixel_values_videos: torch.FloatTensor | None = None,
            image_grid_thw: torch.LongTensor | None = None,
            video_grid_thw: torch.LongTensor | None = None,
            mm_token_type_ids: torch.IntTensor | None = None,
            logits_to_keep: int | torch.Tensor = 0,
            **kwargs: Unpack[TransformersKwargs],
    ) -> tuple | Qwen3VLCausalLMOutputWithPast:
        r"""
        labels (`torch.LongTensor` of shape `(batch_size, sequence_length)`, *optional*):
            Labels for computing the masked language modeling loss. Indices should either be in `[0, ...,
            config.vocab_size]` or -100 (see `input_ids` docstring). Tokens with indices set to `-100` are ignored
            (masked), the loss is only computed for the tokens with labels in `[0, ..., config.vocab_size]`.
        image_grid_thw (`torch.LongTensor` of shape `(num_images, 3)`, *optional*):
            The temporal, height and width of feature shape of each image in LLM.
        video_grid_thw (`torch.LongTensor` of shape `(num_videos, 3)`, *optional*):
            The temporal, height and width of feature shape of each video in LLM.

        Example:

        ```python
        >>> from transformers import AutoProcessor, Qwen3VLForConditionalGeneration

        >>> model = Qwen3VLForConditionalGeneration.from_pretrained("Qwen/Qwen3-VL-8B-Instruct")
        >>> processor = AutoProcessor.from_pretrained("Qwen/Qwen3-VL-8B-Instruct")

        >>> messages = [
            {
                "role": "user",
                "content": [
                    {
                        "type": "image",
                        "image": "https://huggingface.co/datasets/huggingface/documentation-images/resolve/main/pipeline-cat-chonk.jpeg",
                    },
                    {"type": "text", "text": "Describe the image."},
                ],
            }
        ]

        >>> inputs = processor.apply_chat_template(
            messages,
            tokenize=True,
            add_generation_prompt=True,
            return_dict=True,
            return_tensors="pt"
        )

        >>> # Generate
        >>> generated_ids = model.generate(**inputs, max_new_tokens=1024)
        >>> generated_ids_trimmed = [out_ids[len(in_ids) :] for in_ids, out_ids in zip(inputs.input_ids, generated_ids)]
        >>> output_text = processor.batch_decode(generated_ids_trimmed, skip_special_tokens=True, clean_up_tokenization_spaces=False)[0]
        >>> print(output_text)
            """

        outputs = self.model(
            input_ids=input_ids,
            pixel_values=pixel_values,
            pixel_values_videos=pixel_values_videos,
            image_grid_thw=image_grid_thw,
            video_grid_thw=video_grid_thw,
            position_ids=position_ids,
            attention_mask=attention_mask,
            past_key_values=past_key_values,
            inputs_embeds=inputs_embeds,
            mm_token_type_ids=mm_token_type_ids,
            **kwargs,
        )

        hidden_states = outputs[0]

        # Only compute necessary logits, and do not upcast them to float if we are not computing the loss
        slice_indices = slice(-logits_to_keep, None) if isinstance(logits_to_keep, int) else logits_to_keep
        logits = self.lm_head(hidden_states[:, slice_indices, :])

        loss = None
        if labels is not None:
            loss = self.loss_function(logits=logits, labels=labels, vocab_size=self.config.text_config.vocab_size)

        return Qwen3VLCausalLMOutputWithPast(
            loss=loss,
            logits=logits,
            past_key_values=outputs.past_key_values,
            hidden_states=outputs.hidden_states,
            attentions=outputs.attentions,
            rope_deltas=outputs.rope_deltas,
        )

    def prepare_inputs_for_generation(
            self,
            input_ids,
            past_key_values=None,
            attention_mask=None,
            inputs_embeds=None,
            position_ids=None,
            use_cache=True,
            pixel_values=None,
            pixel_values_videos=None,
            image_grid_thw=None,
            video_grid_thw=None,
            is_first_iteration=False,
            **kwargs,
    ):
        # Overwritten -- in specific circumstances we don't want to forward image inputs to the model

        model_inputs = super().prepare_inputs_for_generation(
            input_ids,
            past_key_values=past_key_values,
            attention_mask=attention_mask,
            inputs_embeds=inputs_embeds,
            position_ids=position_ids,
            pixel_values=pixel_values,
            pixel_values_videos=pixel_values_videos,
            image_grid_thw=image_grid_thw,
            video_grid_thw=video_grid_thw,
            use_cache=use_cache,
            is_first_iteration=is_first_iteration,
            **kwargs,
        )

        if not is_first_iteration and use_cache:
            model_inputs["pixel_values"] = None
            model_inputs["pixel_values_videos"] = None

        return model_inputs

    def _prepare_position_ids_for_generation(self, inputs_tensor, model_kwargs):
        # Overwritten -- requires 3D position ids

        text_positions = super()._prepare_position_ids_for_generation(inputs_tensor, model_kwargs)

        # Early exit in case we are continuing generation from past kv
        past_length = 0
        if (cache := model_kwargs.get("past_key_values")) is not None:
            past_length = cache.get_seq_length()
        if past_length != 0 and self.model.rope_deltas is not None:
            position_ids = text_positions[None, ...] + self.model.rope_deltas
            return position_ids

        # Otherwise compute 3d position ids for vision tokens and concat with text position ids
        if "input_ids" in model_kwargs and model_kwargs["input_ids"].shape[1] > 0:
            inputs_tensor = model_kwargs["input_ids"]

        is_input_ids = len(inputs_tensor.shape) == 2 and inputs_tensor.dtype in [torch.int, torch.long]
        if (
                is_input_ids
                and model_kwargs.get("mm_token_type_ids") is not None
                and (model_kwargs.get("image_grid_thw") is not None or model_kwargs.get("video_grid_thw") is not None)
        ):
            model_kwargs = {k: v for k, v in model_kwargs.items() if k != "input_ids"}
            vision_positions, rope_deltas = self.model.get_rope_index(inputs_tensor, **model_kwargs)
            self.model.rope_deltas = rope_deltas
        else:
            vision_positions = text_positions.unsqueeze(0).expand(3, -1, -1)
            self.model.rope_deltas = torch.zeros(
                inputs_tensor.shape[0], 1, dtype=torch.long, device=inputs_tensor.device
            )

        # Concatenate "text + vision" positions into [4, bs, seq-len]
        text_positions = text_positions[None, ...]
        position_ids = torch.cat([text_positions, vision_positions], dim=0)

        return position_ids

    def _get_image_nums_and_video_nums(
            self,
            input_ids: torch.LongTensor | None,
            inputs_embeds: torch.Tensor | None = None,
    ) -> tuple[torch.Tensor, torch.Tensor]:
        """
        Get the number of images and videos for each sample to calculate the separation length of the sample tensor.
        These parameters are not passed through the processor to avoid unpredictable impacts from interface modifications.

        Args:
            input_ids (`torch.LongTensor` of shape `(batch_size, sequence_length)`):
                Indices of input sequence tokens in the vocabulary.

        Returns:
            image_nums (`torch.LongTensor` of shape `(batch_size, num_images_sample)`)
            video_nums (`torch.LongTensor` of shape `(batch_size, num_videos_sample)`)
        """
        image_token_id = self.config.image_token_id
        video_token_id = self.config.video_token_id
        vision_start_token_id = self.config.vision_start_token_id

        if inputs_embeds is not None:
            vision_start_mask = (
                    inputs_embeds
                    == self.get_input_embeddings()(
                torch.tensor(vision_start_token_id, dtype=torch.long, device=inputs_embeds.device)
            )
            )[..., 0]
            image_mask = (
                    inputs_embeds
                    == self.get_input_embeddings()(
                torch.tensor(image_token_id, dtype=torch.long, device=inputs_embeds.device)
            )
            )[..., 0]
            video_mask = (
                    inputs_embeds
                    == self.get_input_embeddings()(
                torch.tensor(video_token_id, dtype=torch.long, device=inputs_embeds.device)
            )
            )[..., 0]
        else:
            vision_start_mask = input_ids == vision_start_token_id
            image_mask = input_ids == image_token_id
            video_mask = input_ids == video_token_id

        vision_first_mask = torch.roll(vision_start_mask, shifts=1, dims=1)
        image_nums = torch.sum(vision_first_mask & image_mask, dim=1)
        video_nums = torch.sum(vision_first_mask & video_mask, dim=1)

        return image_nums, video_nums

    def _expand_inputs_for_generation(
            self,
            expand_size: int = 1,
            is_encoder_decoder: bool = False,
            input_ids: torch.LongTensor | None = None,
            **model_kwargs,
    ) -> tuple[torch.LongTensor, dict[str, Any]]:
        # Overwritten -- Qwen3VL use timestamps and remove second_per_grid_ts
        # Support for expanding tensors without a batch size dimension
        # e.g., pixel_values, image_grid_thw, pixel_values_videos, video_grid_thw
        # pixel_values.shape[0] is sum(seqlen_images for samples)
        # image_grid_thw.shape[0] is sum(num_images for samples)

        if expand_size == 1:
            return input_ids, model_kwargs

        visual_keys = ["pixel_values", "image_grid_thw", "pixel_values_videos", "video_grid_thw"]

        def _expand_dict_for_generation_visual(dict_to_expand):
            image_grid_thw = model_kwargs.get("image_grid_thw", None)
            video_grid_thw = model_kwargs.get("video_grid_thw", None)
            image_nums, video_nums = self._get_image_nums_and_video_nums(
                input_ids, inputs_embeds=model_kwargs.get("inputs_embeds", None)
            )

            # video_nums: (batch_size,)
            # since video_nums is the number of videos in the input dependent on the input_ids(vision_start),
            # but qwen3vl append vision_start to each frame of each video, so we need to recover the real video_nums according to video_grid_thw
            if video_grid_thw is not None:
                cumulative_frame_counts = torch.cumsum(video_grid_thw[:, 0], dim=0)
                cumulative_token_video_counts = torch.cumsum(video_nums, dim=0)
                # Find video boundaries in cumulative_frame_counts
                video_boundary_indices = torch.searchsorted(cumulative_frame_counts, cumulative_token_video_counts)
                # example: video_boundary_indices = [3, 5] means video_nums = [4, 2]
                video_nums = torch.diff(torch.cat([-video_boundary_indices.new_ones(1), video_boundary_indices]))

            def _repeat_interleave_samples(x, lengths, repeat_times):
                samples = torch.split(x, lengths)
                repeat_args = [repeat_times] + [1] * (x.dim() - 1)
                result = torch.cat([sample.repeat(*repeat_args) for sample in samples], dim=0)
                return result

            for key in dict_to_expand:
                if key == "pixel_values":
                    # split images into samples
                    samples = torch.split(image_grid_thw, list(image_nums))
                    # compute the sequence length of images for each sample
                    lengths = [torch.prod(sample, dim=1).sum() for sample in samples]
                    dict_to_expand[key] = _repeat_interleave_samples(
                        dict_to_expand[key], lengths=lengths, repeat_times=expand_size
                    )
                elif key == "image_grid_thw":
                    # get the num of images for each sample
                    lengths = list(image_nums)
                    dict_to_expand[key] = _repeat_interleave_samples(
                        dict_to_expand[key], lengths=lengths, repeat_times=expand_size
                    )
                elif key == "pixel_values_videos":
                    samples = torch.split(video_grid_thw, list(video_nums))
                    lengths = [torch.prod(sample, dim=1).sum() for sample in samples]
                    dict_to_expand[key] = _repeat_interleave_samples(
                        dict_to_expand[key], lengths=lengths, repeat_times=expand_size
                    )
                elif key == "video_grid_thw":
                    lengths = list(video_nums)
                    dict_to_expand[key] = _repeat_interleave_samples(
                        dict_to_expand[key], lengths=lengths, repeat_times=expand_size
                    )
            return dict_to_expand

        def _expand_dict_for_generation(dict_to_expand):
            for key in dict_to_expand:
                if key == "position_ids" and dict_to_expand[key].ndim == 3:
                    dict_to_expand[key] = dict_to_expand[key].repeat_interleave(expand_size, dim=1)
                elif (
                        dict_to_expand[key] is not None
                        and isinstance(dict_to_expand[key], torch.Tensor)
                        and key not in visual_keys
                ):
                    dict_to_expand[key] = dict_to_expand[key].repeat_interleave(expand_size, dim=0)
            return dict_to_expand

        model_kwargs = _expand_dict_for_generation_visual(model_kwargs)

        if input_ids is not None:
            input_ids = input_ids.repeat_interleave(expand_size, dim=0)

        model_kwargs = _expand_dict_for_generation(model_kwargs)

        if is_encoder_decoder:
            if model_kwargs.get("encoder_outputs") is None:
                raise ValueError("If `is_encoder_decoder` is True, make sure that `encoder_outputs` is defined.")
            model_kwargs["encoder_outputs"] = _expand_dict_for_generation(model_kwargs["encoder_outputs"])

        return input_ids, model_kwargs

__all__ = [
    "Qwen3VLVisionModel",
    "Qwen3VLForConditionalGeneration",
    "Qwen3VLModel",
    "Qwen3VLPreTrainedModel",
    "Qwen3VLTextModel",
]
